/**
 * Arlo UI — Card
 *
 * Compound component:
 *   <Card>, <Card.Media>, <Card.Header>, <Card.Title>, <Card.Subtitle>, <Card.Body>, <Card.Footer>
 *
 * Two independent axes:
 *   - `tone`:    how much the card lifts off the page — 'default' · 'raised' · 'floating'.
 *   - `surface`: what it's made of — 'default' opaque fill, or 'glass' for the
 *                translucent Liquid Glass material (pair with `blurComponent`).
 *
 * Geometry is three more, all reading off the token scales so a card never invents
 * a value: `padding` and `margin` share one spacing scale ('none' … 'xl'), and
 * `radius` maps straight onto the radius scale ('none' … 'full'). The presets and
 * `ListCard.Group` forward `margin` and `radius` too, so a row of cards can be
 * reshaped without dropping to `style`.
 *
 * Surfaces use `surface` by default and step up to `surfaceRaised` for the `raised`
 * tone. Borders carry hierarchy on neutral surfaces — shadows are reserved for
 * `floating` (modal/menu separation only). Per the design skill, depth comes from
 * layering and spacing first, not shadows.
 *
 * Pass `onPress` to make the whole card a single tap target; it picks up the same
 * press feedback as the rest of the system and reports itself as a button.
 */
import { type ReactNode } from 'react';
import {
  Pressable,
  Text,
  View,
  type PressableProps,
  type StyleProp,
  type TextStyle,
  type ViewStyle,
} from 'react-native';
import { GlassBackdrop, useGlassSurface } from '../../foundation/glass';
import { useTokens } from '../../foundation/theme-provider';

type Tone = 'default' | 'raised' | 'floating';
export type CardSurface = 'default' | 'glass';

/**
 * One scale for both `padding` and `margin`, so "sm" means the same distance
 * whichever side of the border it lands on.
 */
export type CardSpacing = 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl';
/** @deprecated Prefer `CardSpacing` — the same scale now covers margin too. */
export type CardPadding = CardSpacing;

/** Corner rounding, straight off the radius scale. */
export type CardRadius = 'none' | 'sm' | 'md' | 'lg' | 'xl' | '2xl' | 'full';

type CardProps = {
  children: ReactNode;
  tone?: Tone;
  /** `'glass'` swaps the opaque fill for the translucent Liquid Glass material. */
  surface?: CardSurface;
  /** Optional blur layer (e.g. `expo-blur`'s BlurView) rendered behind a glass surface. */
  blurComponent?: ReactNode;
  /** Inner padding. Use `'none'` when the card is edge-to-edge media. */
  padding?: CardSpacing;
  /**
   * Outer spacing. Layout is usually the parent's job — reach for a `gap` on the
   * list before reaching for this — but a card dropped into a screen you don't
   * control needs a way to hold itself off the edges.
   */
  margin?: CardSpacing;
  /** Corner rounding. Defaults to `'xl'`, the standard card radius. */
  radius?: CardRadius;
  /** Makes the whole card a tap target with press feedback and `accessibilityRole="button"`. */
  onPress?: PressableProps['onPress'];
  onLongPress?: PressableProps['onLongPress'];
  disabled?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

function CardRoot({
  children,
  tone = 'default',
  surface = 'default',
  blurComponent,
  padding = 'md',
  margin = 'none',
  radius = 'xl',
  onPress,
  onLongPress,
  disabled = false,
  accessibilityLabel,
  style,
}: CardProps) {
  const t = useTokens();
  // Cards are large surfaces, so they take the heaviest material — content behind a
  // card should read as background texture, not as competing detail.
  const glass = useGlassSurface('large');
  const isGlass = surface === 'glass';
  const interactive = onPress != null || onLongPress != null;

  // `sm`/`md`/`lg` keep the values they already had, so existing cards don't shift.
  const spacingScale: Record<CardSpacing, number> = {
    none: 0,
    xs: t.spacing[2],
    sm: t.spacing[3],
    md: t.spacing[5],
    lg: t.spacing[6],
    xl: t.spacing[8],
  };
  const paddingValue = spacingScale[padding];
  const marginValue = spacingScale[margin];

  const bg = isGlass
    ? glass.backgroundColor
    : tone === 'raised'
      ? t.colors.surfaceRaised
      : tone === 'floating'
        ? t.colors.surfaceStrong
        : t.colors.surface;

  const containerStyle: ViewStyle = {
    backgroundColor: bg,
    borderColor: isGlass ? glass.borderColor : t.colors.border,
    borderWidth: 1,
    borderRadius: t.radii[radius],
    padding: paddingValue,
    margin: marginValue,
    gap: padding === 'none' ? 0 : t.spacing[3],
    // Clip media and the blur layer to the card's corners.
    overflow: 'hidden',
    opacity: disabled ? 0.45 : 1,
  };

  const shadow = tone === 'floating' ? (t.shadows.md as ViewStyle) : null;

  if (!interactive) {
    return (
      <View style={[containerStyle, shadow, style]}>
        {isGlass ? <GlassBackdrop>{blurComponent}</GlassBackdrop> : null}
        {children}
      </View>
    );
  }

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
      accessibilityState={{ disabled }}
      disabled={disabled}
      onPress={onPress}
      onLongPress={onLongPress}
      style={({ pressed }) => [
        containerStyle,
        shadow,
        pressed && !disabled
          ? { opacity: t.motion.pressed.opacity, transform: [{ scale: t.motion.pressed.scale }] }
          : null,
        style,
      ]}
    >
      {isGlass ? <GlassBackdrop>{blurComponent}</GlassBackdrop> : null}
      {children}
    </Pressable>
  );
}

/**
 * Edge-to-edge media slot. Pair with `padding="none"` on the card and put the text
 * content in a padded `Card.Body` so the image bleeds to the card's corners.
 */
function CardMedia({
  children,
  height,
  style,
}: {
  children: ReactNode;
  /** Fixed media height. Omit to let the child size itself (e.g. an aspect-ratio image). */
  height?: number;
  style?: StyleProp<ViewStyle>;
}) {
  return (
    <View style={[{ height, width: '100%', overflow: 'hidden' }, style]}>{children}</View>
  );
}

function CardHeader({ children, style }: { children: ReactNode; style?: StyleProp<ViewStyle> }) {
  const t = useTokens();
  return <View style={[{ gap: t.spacing[1] }, style]}>{children}</View>;
}

function CardTitle({ children, style }: { children: ReactNode; style?: StyleProp<TextStyle> }) {
  const t = useTokens();
  return (
    <Text
      style={[
        {
          color: t.colors.textPrimary,
          fontFamily: t.fontFamilies.sans,
          fontSize: t.typography.title2.fontSize,
          lineHeight: t.typography.title2.lineHeight,
          fontWeight: '600',
        },
        style,
      ]}
    >
      {children}
    </Text>
  );
}

function CardSubtitle({ children, style }: { children: ReactNode; style?: StyleProp<TextStyle> }) {
  const t = useTokens();
  return (
    <Text
      style={[
        {
          color: t.colors.textSecondary,
          fontFamily: t.fontFamilies.sans,
          fontSize: t.typography.bodySm.fontSize,
          lineHeight: t.typography.bodySm.lineHeight,
        },
        style,
      ]}
    >
      {children}
    </Text>
  );
}

function CardBody({
  children,
  padded = false,
  style,
}: {
  children: ReactNode;
  /** Restores the card's inner padding for this section when the card is `padding="none"`. */
  padded?: boolean;
  style?: StyleProp<ViewStyle>;
}) {
  const t = useTokens();
  return (
    <View style={[padded ? { padding: t.spacing[5], gap: t.spacing[3] } : null, style]}>
      {children}
    </View>
  );
}

function CardFooter({ children, style }: { children: ReactNode; style?: StyleProp<ViewStyle> }) {
  const t = useTokens();
  return (
    <View
      style={[
        { flexDirection: 'row', alignItems: 'center', justifyContent: 'flex-end', gap: t.spacing[2] },
        style,
      ]}
    >
      {children}
    </View>
  );
}

export const Card = Object.assign(CardRoot, {
  Media: CardMedia,
  Header: CardHeader,
  Title: CardTitle,
  Subtitle: CardSubtitle,
  Body: CardBody,
  Footer: CardFooter,
});

export type { CardProps };

/**
 * Arlo UI — StatCard
 *
 * A single metric with its context: what it is, what it is now, and which way it
 * moved. The number rolls on the shared counter, so a stat that updates live
 * animates instead of snapping.
 *
 *   <StatCard label="Balance" value={12480.32} format={money}
 *             delta={412.19} trend={points} />
 *
 * The delta always renders a sign. The tone tokens it uses sit near the
 * deuteranopia separation floor, so the sign — not the colour — is what makes
 * direction readable. Passing `delta` without letting it show a sign is not an
 * option, by design.
 */
import { type ReactNode } from 'react';
import { Text, View, type PressableProps, type StyleProp, type ViewStyle } from 'react-native';
import { AnimatedCounter } from '../animated-counter/animated-counter';
import { Sparkline } from '../chart/sparkline';
import { useTokens } from '../../foundation/theme-provider';
import { Card, type CardProps } from './card';

export type StatCardProps = {
  label: string;
  value: number;
  /** Formats both the value and the delta. */
  format?: (value: number) => string;
  /** Change against the previous period. Rendered signed, never bare. */
  delta?: number;
  /** Show the delta as a percentage beside the absolute change. */
  deltaPercent?: number;
  /** Optional inline sparkline. Toned from `delta` when given, else from its own shape. */
  trend?: number[];
  /** Small glyph in the top-right — a category icon, a menu affordance. */
  icon?: ReactNode;
  /** Extra context under the value, e.g. "vs last month". */
  caption?: string;
  tone?: CardProps['tone'];
  surface?: CardProps['surface'];
  /** Outer spacing, forwarded to `Card`. */
  margin?: CardProps['margin'];
  /** Corner rounding, forwarded to `Card`. */
  radius?: CardProps['radius'];

  blurComponent?: CardProps['blurComponent'];
  onPress?: PressableProps['onPress'];
  style?: StyleProp<ViewStyle>;
};

export function StatCard({
  label,
  value,
  format,
  delta,
  deltaPercent,
  trend,
  icon,
  caption,
  tone,
  surface,
  margin,
  radius,
  blurComponent,
  onPress,
  style,
}: StatCardProps) {
  const t = useTokens();
  const hasDelta = delta != null && delta !== 0;
  const rising = (delta ?? 0) > 0;
  const deltaColor = hasDelta
    ? rising
      ? t.colors.chartPositive
      : t.colors.chartNegative
    : t.colors.textSecondary;
  // U+2212, not a hyphen — a hyphen reads as a dash at this size.
  const sign = delta == null || delta === 0 ? '' : rising ? '+' : '−';
  const deltaText = delta == null ? null : format ? format(Math.abs(delta)) : String(Math.abs(delta));

  return (
    <Card
      tone={tone}
      surface={surface}
      margin={margin}
      radius={radius}
      blurComponent={blurComponent}
      padding="md"
      onPress={onPress}
      accessibilityLabel={onPress ? label : undefined}
      style={style}
    >
      <View style={{ flexDirection: 'row', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <Text
          numberOfLines={1}
          style={{
            flexShrink: 1,
            color: t.colors.textSecondary,
            fontFamily: t.fontFamilies.sans,
            fontSize: t.typography.bodySm.fontSize,
            lineHeight: t.typography.bodySm.lineHeight,
            fontWeight: '600',
          }}
        >
          {label}
        </Text>
        {icon ? <View style={{ marginLeft: t.spacing[2] }}>{icon}</View> : null}
      </View>

      <View style={{ alignItems: 'flex-start' }}>
        <AnimatedCounter
          text={format ? format(value) : String(value)}
          fontSize={t.typography.title1.fontSize}
          lineHeight={t.typography.title1.lineHeight}
          color={t.colors.textPrimary}
          fontFamily={t.fontFamilies.sans}
          fontWeight="700"
        />
      </View>

      {deltaText != null || trend || caption ? (
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: t.spacing[2] }}>
          {deltaText != null ? (
            <Text
              style={{
                color: deltaColor,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
                fontWeight: '600',
              }}
            >
              {sign}
              {deltaText}
              {deltaPercent != null ? ` (${sign}${Math.abs(deltaPercent).toFixed(2)}%)` : ''}
            </Text>
          ) : null}

          {caption ? (
            <Text
              numberOfLines={1}
              style={{
                flexShrink: 1,
                color: t.colors.textTertiary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
              }}
            >
              {caption}
            </Text>
          ) : null}

          {trend && trend.length > 1 ? (
            <View style={{ flex: 1, minWidth: 48, alignItems: 'flex-end' }}>
              <Sparkline
                data={trend}
                height={24}
                // The delta is the source of truth for direction when it is given,
                // so the sparkline can't disagree with the number above it.
                tone={delta == null ? 'auto' : rising ? 'positive' : 'negative'}
              />
            </View>
          ) : null}
        </View>
      ) : null}
    </Card>
  );
}

/**
 * Arlo UI — ListCard
 *
 * The workhorse row: something on the left, a title and a supporting line in the
 * middle, a value or affordance on the right. Transactions, settings, contacts,
 * search results.
 *
 *   <ListCard.Group>
 *     <ListCard leading={<Avatar />} title="Spotify" subtitle="Yesterday"
 *               value="−$9.99" chevron onPress={open} />
 *     <ListCard title="Transfer" subtitle="Mar 3" value="+$1,200" chevron />
 *   </ListCard.Group>
 *
 * `Group` is what makes rows read as one list: it draws the surface and the
 * hairlines *between* rows only, so the outer corners stay clean and there is no
 * stray rule above the first row or below the last. Rows used on their own get
 * their own surface instead.
 */
import { Children, cloneElement, isValidElement, type ReactElement, type ReactNode } from 'react';
import {
  Pressable,
  Text,
  View,
  type PressableProps,
  type StyleProp,
  type ViewStyle,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';
import { useTokens } from '../../foundation/theme-provider';
import type { CardRadius, CardSpacing } from './card';

export type ListCardProps = {
  title: string;
  subtitle?: string;
  /** Leading slot — avatar, icon, thumbnail. */
  leading?: ReactNode;
  /** Trailing text, e.g. an amount. Rendered before the chevron. */
  value?: string;
  /** Secondary line under `value`. */
  valueCaption?: string;
  /** Tone for `value` — amounts usually want direction. */
  valueTone?: 'default' | 'positive' | 'negative';
  /** Arbitrary trailing slot. Replaces `value` when both are given. */
  trailing?: ReactNode;
  /** Show a disclosure chevron. Implies the row goes somewhere. */
  chevron?: boolean;
  disabled?: boolean;
  onPress?: PressableProps['onPress'];
  onLongPress?: PressableProps['onLongPress'];
  /** Set by `ListCard.Group`; rows inside a group don't paint their own surface. */
  inGroup?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

function ChevronIcon({ color, size }: { color: string; size: number }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
      <Path
        d="M9 6l6 6-6 6"
        stroke={color}
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </Svg>
  );
}

function ListCardRow({
  title,
  subtitle,
  leading,
  value,
  valueCaption,
  valueTone = 'default',
  trailing,
  chevron = false,
  disabled = false,
  onPress,
  onLongPress,
  inGroup = false,
  accessibilityLabel,
  style,
}: ListCardProps) {
  const t = useTokens();
  const interactive = onPress != null || onLongPress != null;

  const valueColor =
    valueTone === 'positive'
      ? t.colors.chartPositive
      : valueTone === 'negative'
        ? t.colors.chartNegative
        : t.colors.textPrimary;

  const content = (
    <>
      {leading ? (
        <View style={{ flexShrink: 0, alignItems: 'center', justifyContent: 'center' }}>{leading}</View>
      ) : null}

      <View style={{ flex: 1, minWidth: 0, gap: 2 }}>
        <Text
          numberOfLines={1}
          style={{
            color: t.colors.textPrimary,
            fontFamily: t.fontFamilies.sans,
            fontSize: t.typography.body.fontSize,
            lineHeight: t.typography.body.lineHeight,
            fontWeight: '600',
          }}
        >
          {title}
        </Text>
        {subtitle ? (
          <Text
            numberOfLines={1}
            style={{
              color: t.colors.textSecondary,
              fontFamily: t.fontFamilies.sans,
              fontSize: t.typography.bodySm.fontSize,
              lineHeight: t.typography.bodySm.lineHeight,
            }}
          >
            {subtitle}
          </Text>
        ) : null}
      </View>

      {trailing ?? (
        value != null ? (
          <View style={{ flexShrink: 0, alignItems: 'flex-end', gap: 2 }}>
            <Text
              numberOfLines={1}
              style={{
                color: valueColor,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.body.fontSize,
                lineHeight: t.typography.body.lineHeight,
                fontWeight: '600',
              }}
            >
              {value}
            </Text>
            {valueCaption ? (
              <Text
                numberOfLines={1}
                style={{
                  color: t.colors.textTertiary,
                  fontFamily: t.fontFamilies.sans,
                  fontSize: t.typography.bodySm.fontSize,
                  lineHeight: t.typography.bodySm.lineHeight,
                }}
              >
                {valueCaption}
              </Text>
            ) : null}
          </View>
        ) : null
      )}

      {chevron ? (
        <View style={{ flexShrink: 0 }}>
          <ChevronIcon color={t.colors.textTertiary} size={t.sizing.icon.sm} />
        </View>
      ) : null}
    </>
  );

  const rowStyle: ViewStyle = {
    flexDirection: 'row',
    alignItems: 'center',
    gap: t.spacing[3],
    minHeight: t.sizing.touchTarget.minimum,
    paddingVertical: t.spacing[3],
    paddingHorizontal: t.spacing[4],
    // Standalone rows carry their own surface; grouped rows inherit the group's.
    backgroundColor: inGroup ? 'transparent' : t.colors.surface,
    borderRadius: inGroup ? 0 : t.radii.xl,
    borderWidth: inGroup ? 0 : 1,
    borderColor: t.colors.border,
    opacity: disabled ? 0.45 : 1,
  };

  if (!interactive) {
    return <View style={[rowStyle, style]}>{content}</View>;
  }

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel ?? title}
      accessibilityState={{ disabled }}
      disabled={disabled}
      onPress={onPress}
      onLongPress={onLongPress}
      style={({ pressed }) => [
        rowStyle,
        pressed && !disabled ? { backgroundColor: t.colors.surfaceInput } : null,
        style,
      ]}
    >
      {content}
    </Pressable>
  );
}

/**
 * Wraps rows into one surface with hairlines between them. Separators go between
 * rows only — a rule above the first or below the last would fight the card edge.
 */
function ListCardGroup({
  children,
  margin = 'none',
  radius = 'xl',
  style,
}: {
  children: ReactNode;
  /** Outer spacing, matching `Card`'s scale. */
  margin?: CardSpacing;
  /** Corner rounding, matching `Card`'s scale. */
  radius?: CardRadius;
  style?: StyleProp<ViewStyle>;
}) {
  const t = useTokens();
  const marginValue = {
    none: 0,
    xs: t.spacing[2],
    sm: t.spacing[3],
    md: t.spacing[5],
    lg: t.spacing[6],
    xl: t.spacing[8],
  }[margin];
  const rows = Children.toArray(children).filter(isValidElement) as ReactElement<ListCardProps>[];

  return (
    <View
      style={[
        {
          backgroundColor: t.colors.surface,
          borderRadius: t.radii[radius],
          borderWidth: 1,
          borderColor: t.colors.border,
          margin: marginValue,
          overflow: 'hidden',
        },
        style,
      ]}
    >
      {rows.map((row, index) => (
        <View key={index}>
          {index > 0 ? (
            <View
              style={{
                height: 1,
                // Inset so the rule starts past the leading slot, like a native list.
                marginLeft: t.spacing[4],
                backgroundColor: t.colors.borderSecondary,
              }}
            />
          ) : null}
          {/* Rows can't know they're grouped, so the group tells them. */}
          {cloneElement(row, { inGroup: true })}
        </View>
      ))}
    </View>
  );
}

export const ListCard = Object.assign(ListCardRow, { Group: ListCardGroup });

/**
 * Arlo UI — MediaCard
 *
 * An image-led card in the two layouts that actually differ:
 *
 *   - `layout="below"`  — cover image, then text on the card surface. The default,
 *     and the safe one: text on a solid surface always meets contrast.
 *   - `layout="overlay"` — text sits on the image. Only legible with a scrim, so
 *     one is always drawn; there is no way to turn it off, because an unscrimmed
 *     overlay is unreadable over a light photo.
 *
 *   <MediaCard media={<Image source={cover} style={StyleSheet.absoluteFill} />}
 *              title="Kyoto" subtitle="12 photos" onPress={open} />
 *
 * The media slot takes any node — an `Image`, a video poster, a gradient — and is
 * clipped to the card's corners.
 */
import { type ReactNode } from 'react';
import { Text, View, type PressableProps, type StyleProp, type ViewStyle } from 'react-native';
import { useTokens } from '../../foundation/theme-provider';
import { Card, type CardProps } from './card';

export type MediaCardLayout = 'below' | 'overlay';

export type MediaCardProps = {
  /** Fills the media area. Give it `StyleSheet.absoluteFill` or a 100% size. */
  media: ReactNode;
  title: string;
  subtitle?: string;
  layout?: MediaCardLayout;
  /** Media height for `below`; total card height for `overlay`. */
  mediaHeight?: number;
  /** Pinned to the top-left of the media — a badge, a duration, a category chip. */
  badge?: ReactNode;
  /** Rendered under the text. Actions, metadata, a button row. */
  footer?: ReactNode;
  tone?: CardProps['tone'];
  /** Outer spacing, forwarded to `Card`. */
  margin?: CardProps['margin'];
  /** Corner rounding, forwarded to `Card`. */
  radius?: CardProps['radius'];

  onPress?: PressableProps['onPress'];
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

export function MediaCard({
  media,
  title,
  subtitle,
  layout = 'below',
  mediaHeight = layout === 'overlay' ? 200 : 160,
  badge,
  footer,
  tone,
  margin,
  radius,
  onPress,
  accessibilityLabel,
  style,
}: MediaCardProps) {
  const t = useTokens();
  const overlay = layout === 'overlay';

  return (
    <Card
      tone={tone}
      padding="none"
      margin={margin}
      radius={radius}
      onPress={onPress}
      accessibilityLabel={accessibilityLabel ?? title}
      style={style}
    >
      <View style={{ height: mediaHeight, width: '100%', overflow: 'hidden' }}>
        {media}

        {overlay ? (
          <>
            {/*
              Scrim: a plain dark wash rather than a gradient, because RN has no
              CSS gradients and pulling in a gradient dependency for one card is a
              poor trade. It is opaque enough to hold white text over a light photo.
            */}
            <View
              pointerEvents="none"
              style={{
                position: 'absolute',
                left: 0,
                right: 0,
                bottom: 0,
                top: '35%',
                backgroundColor: 'rgba(16,24,40,0.55)',
              }}
            />
            <View
              style={{
                position: 'absolute',
                left: 0,
                right: 0,
                bottom: 0,
                padding: t.spacing[4],
                gap: 2,
              }}
            >
              <Text
                numberOfLines={2}
                style={{
                  // Fixed white, not a token: this sits on the scrim, not on a themed
                  // surface, so it must not flip with the colour scheme.
                  color: '#FFFFFF',
                  fontFamily: t.fontFamilies.sans,
                  fontSize: t.typography.title3.fontSize,
                  lineHeight: t.typography.title3.lineHeight,
                  fontWeight: '700',
                }}
              >
                {title}
              </Text>
              {subtitle ? (
                <Text
                  numberOfLines={1}
                  style={{
                    color: 'rgba(255,255,255,0.86)',
                    fontFamily: t.fontFamilies.sans,
                    fontSize: t.typography.bodySm.fontSize,
                    lineHeight: t.typography.bodySm.lineHeight,
                  }}
                >
                  {subtitle}
                </Text>
              ) : null}
            </View>
          </>
        ) : null}

        {badge ? (
          <View style={{ position: 'absolute', top: t.spacing[3], left: t.spacing[3] }}>{badge}</View>
        ) : null}
      </View>

      {!overlay ? (
        <View style={{ padding: t.spacing[4], gap: 2 }}>
          <Text
            numberOfLines={2}
            style={{
              color: t.colors.textPrimary,
              fontFamily: t.fontFamilies.sans,
              fontSize: t.typography.title3.fontSize,
              lineHeight: t.typography.title3.lineHeight,
              fontWeight: '700',
            }}
          >
            {title}
          </Text>
          {subtitle ? (
            <Text
              numberOfLines={2}
              style={{
                color: t.colors.textSecondary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
              }}
            >
              {subtitle}
            </Text>
          ) : null}
          {footer ? <View style={{ marginTop: t.spacing[2] }}>{footer}</View> : null}
        </View>
      ) : footer ? (
        <View style={{ padding: t.spacing[4] }}>{footer}</View>
      ) : null}
    </Card>
  );
}

/**
 * Arlo UI — ActionCard
 *
 * A card that asks for something: finish setup, enable notifications, upgrade.
 * An icon or illustration, a short pitch, and the buttons that resolve it.
 *
 *   <ActionCard
 *     icon={<ShieldIcon />}
 *     title="Turn on two-factor auth"
 *     body="Add a second step when signing in from a new device."
 *     primaryAction={{ label: 'Enable', onPress: enable }}
 *     secondaryAction={{ label: 'Not now', onPress: dismiss }}
 *     onDismiss={dismiss}
 *   />
 *
 * `tone` moves it onto the status palette for the cases where the card reports a
 * state rather than an opportunity. Status colours always ship with the title
 * text beside them, never as the only signal.
 */
import { type ReactNode } from 'react';
import { Pressable, Text, View, type StyleProp, type ViewStyle } from 'react-native';
import Svg, { Path } from 'react-native-svg';
import { Button } from '../button/button';
import { useTokens } from '../../foundation/theme-provider';
import { Card, type CardProps } from './card';

export type ActionCardTone = 'default' | 'info' | 'success' | 'warning' | 'error';

export type ActionCardAction = {
  label: string;
  onPress: () => void;
  loading?: boolean;
  disabled?: boolean;
};

export type ActionCardProps = {
  title: string;
  body?: string;
  /** Leading glyph or illustration. */
  icon?: ReactNode;
  tone?: ActionCardTone;
  primaryAction?: ActionCardAction;
  secondaryAction?: ActionCardAction;
  /** Adds a close affordance in the top-right. */
  onDismiss?: () => void;
  dismissAccessibilityLabel?: string;
  surface?: CardProps['surface'];
  /** Outer spacing, forwarded to `Card`. */
  margin?: CardProps['margin'];
  /** Corner rounding, forwarded to `Card`. */
  radius?: CardProps['radius'];

  blurComponent?: CardProps['blurComponent'];
  /** Stack the buttons full-width instead of sitting them in a row. */
  stackActions?: boolean;
  style?: StyleProp<ViewStyle>;
};

function CloseIcon({ color, size }: { color: string; size: number }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
      <Path
        d="M6 6l12 12M18 6L6 18"
        stroke={color}
        strokeWidth={2}
        strokeLinecap="round"
      />
    </Svg>
  );
}

export function ActionCard({
  title,
  body,
  icon,
  tone = 'default',
  primaryAction,
  secondaryAction,
  onDismiss,
  dismissAccessibilityLabel = 'Dismiss',
  surface,
  margin,
  radius,
  blurComponent,
  stackActions = false,
  style,
}: ActionCardProps) {
  const t = useTokens();

  const accent =
    tone === 'success'
      ? { fg: t.colors.feedbackSuccess, bg: t.colors.feedbackSuccessBg }
      : tone === 'warning'
        ? { fg: t.colors.feedbackWarning, bg: t.colors.feedbackWarningBg }
        : tone === 'error'
          ? { fg: t.colors.feedbackError, bg: t.colors.feedbackErrorBg }
          : tone === 'info'
            ? { fg: t.colors.feedbackInfo, bg: t.colors.feedbackInfoBg }
            : { fg: t.colors.interactivePrimary, bg: t.colors.surfaceInput };

  // A danger card's primary action should read as danger too, so the button tone
  // follows the card rather than defaulting to brand.
  const primaryTone = tone === 'error' ? 'danger' : 'primary';

  return (
    <Card
      surface={surface}
      blurComponent={blurComponent}
      padding="md"
      margin={margin}
      radius={radius}
      style={style}
    >
      <View style={{ flexDirection: 'row', alignItems: 'flex-start', gap: t.spacing[3] }}>
        {icon ? (
          <View
            style={{
              width: 40,
              height: 40,
              borderRadius: t.radii.full,
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: accent.bg,
              flexShrink: 0,
            }}
          >
            {icon}
          </View>
        ) : null}

        <View style={{ flex: 1, minWidth: 0, gap: t.spacing[1] }}>
          <Text
            style={{
              color: t.colors.textPrimary,
              fontFamily: t.fontFamilies.sans,
              fontSize: t.typography.title3.fontSize,
              lineHeight: t.typography.title3.lineHeight,
              fontWeight: '700',
            }}
          >
            {title}
          </Text>
          {body ? (
            <Text
              style={{
                color: t.colors.textSecondary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
              }}
            >
              {body}
            </Text>
          ) : null}
        </View>

        {onDismiss ? (
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={dismissAccessibilityLabel}
            onPress={onDismiss}
            hitSlop={10}
            style={({ pressed }) => ({
              flexShrink: 0,
              opacity: pressed ? t.motion.pressed.opacity : 1,
            })}
          >
            <CloseIcon color={t.colors.textTertiary} size={t.sizing.icon.sm} />
          </Pressable>
        ) : null}
      </View>

      {primaryAction || secondaryAction ? (
        <View
          style={{
            flexDirection: stackActions ? 'column' : 'row',
            alignItems: stackActions ? 'stretch' : 'center',
            justifyContent: 'flex-end',
            gap: t.spacing[2],
          }}
        >
          {secondaryAction ? (
            <Button
              tone="neutral"
              appearance="ghost"
              size="sm"
              fullWidth={stackActions}
              loading={secondaryAction.loading}
              disabled={secondaryAction.disabled}
              onPress={secondaryAction.onPress}
            >
              {secondaryAction.label}
            </Button>
          ) : null}
          {primaryAction ? (
            <Button
              tone={primaryTone}
              appearance="solid"
              size="sm"
              fullWidth={stackActions}
              loading={primaryAction.loading}
              disabled={primaryAction.disabled}
              onPress={primaryAction.onPress}
            >
              {primaryAction.label}
            </Button>
          ) : null}
        </View>
      ) : null}
    </Card>
  );
}

